import numpy as np


def planted(T, d, seed, Tmax=8):
    g = np.random.default_rng(seed)
    X = g.standard_normal((T, d))
    params = {'P': 0.5 * g.standard_normal((Tmax, d))}
    for k in ('Wq', 'Wk', 'Wv', 'Wo'):
        params[k] = g.standard_normal((d, d)) / np.sqrt(d)
    return X, params


X6, P6 = planted(6, 8, 0)
X5, P5 = planted(5, 12, 1)
